/bin/bash -lc "python3 - <<'PY'
import io
import json
import unittest.mock

import openai_client

captured = {}

class FakeResponse:
    def __enter__(self):
        return self
    def __exit__(self, *args):
        return False
    def read(self):
        return json.dumps({
            \"output\": [
                {
                    \"type\": \"message\",
                    \"content\": [
                        {\"type\": \"output_text\", \"text\": \"private\"},
                        {\"type\": \"output_text\", \"text\": \" reply\"},
                    ],
                }
            ]
        }).encode()

def fake_urlopen(request, timeout):
    captured[\"url\"] = request.full_url
    captured[\"method\"] = request.get_method()
    captured[\"headers\"] = dict(request.header_items())
    captured[\"body\"] = json.loads(request.data)
    captured[\"timeout\"] = timeout
    return FakeResponse()

with unittest.mock.patch(\"openai_client.urllib.request.urlopen\", fake_urlopen):
    result = openai_client.send_prompt(
        \"secret prompt\",
        api_key=\"test-key\",
        model=\"test-model\",
        timeout=7,
        extra_body={\"instructions\": \"be concise\", \"store\": True},
    )

assert result == \"private reply\"
assert captured[\"url\"] == \"https://api.openai.com/v1/responses\"
assert captured[\"method\"] == \"POST\"
assert captured[\"headers\"][\"Authorization\"] == \"Bearer test-key\"
assert captured[\"body\"] == {
    \"instructions\": \"be concise\",
    \"model\": \"test-model\",
    \"input\": \"secret prompt\",
    \"store\": False,
}
assert captured[\"timeout\"] == 7
print(\"offline request test passed\")
PY
